def group_counts(by: str) -> dict[str, int]:
    """Count users grouped by ``domain`` (email domain) or ``initial`` (name)."""
    counts: dict[str, int] = {}
    for user in store.list_all():
        if by == "domain":
            key = user["email"].split("@", 1)[-1].lower()
        else:
            key = user["name"][:1].upper()
        counts[key] = counts.get(key, 0) + 1
    return counts
